/* ---------- LA CHAÎNE DE MONTAGNES (haut du plateau) ----------
   Infranchissable : on n'y bâtit pas. Même découpe que les dunes. */
const MONT = { ok: false, mips: {}, hw: 0.790, w: 1.64 };
(function () {
  const img = new Image();
  img.onload = () => { MONT.img = img; MONT.ok = true; };
  img.src = "data:image/webp;base64,";
})();
// Seul le CŒUR du massif est infranchissable : tout son pourtour se
// construit (retour propriétaire). La moyenne des cases reste (1,1), donc le
// dessin du massif ne bouge pas d'un pixel.
const MONT_CELLS = [[1, 1]];
const montSet = new Set(MONT_CELLS.map((c) => c[0] + "," + c[1]));
const MONT_CX = MONT_CELLS.reduce((a, c) => a + c[0], 0) / MONT_CELLS.length;
const MONT_CY = MONT_CELLS.reduce((a, c) => a + c[1], 0) / MONT_CELLS.length;
// Profondeur de TRI de la montagne : haute, son pied s'avance d'environ 2 cases
// devant son ancrage (1,1). On la trie donc à ~(1+1)+2 pour qu'elle OCCULTE les
// bâtiments en retrait derrière elle et passe DERRIÈRE ceux clairement devant.
// Une seule valeur à ajuster si l'occlusion mord trop (baisser) ou pas assez (monter).
const MONT_FRONT = MONT_CX + MONT_CY + 2;
